import React from 'react';

export default function QuickAction({ label, icon, onClick }) {
  return (
    <button
      onClick={onClick}
      className="flex items-center justify-center gap-2 btn-accent w-full border-default transition"
    >
      {icon && <span className="text-lg">{icon}</span>}
      {label}
    </button>
  );
}
